// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz: an arbitrary sender, a list length (tosCount) and a value v
    function testFuzz_property(address from, uint16 tosCountRaw, uint256 v) public {
        // keep tosCount in a reasonable wide domain but as uint256 for loop
        uint256 tosCount = bound(uint256(tosCountRaw), 1, 10);

        // deploy a recorder that implements transferFrom(address,address,uint256)
        Recorder r = new Recorder();

        // build _tos array of length tosCount, all pointing to recorder
        address[] memory tos = new address[](tosCount);
        for (uint256 i = 0; i < tosCount; i++) tos[i] = address(r);

        // call transfer; it will low-level call the recorder with selector for transferFrom
        // record whether it reverted (should not for the reference contract)
        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant (GENERAL RULE): the reference contract always makes exactly tosCount calls
        // that match transferFrom(address,address,uint256) and the recorder increments callCount.
        // We assert that when the call succeeds, recorder.callCount == tosCount.
        // This will hold for the reference implementation for all inputs, but the mutant
        // that uses the wrong selector can cause fewer or zero transferFrom calls to be observed
        // for some inputs, causing this assertion to fail.
        if (ok) {
            assertTrue(r.callCount() == tosCount);
        } else {
            // If the call itself reverted, the reference contract's require(_tos.length > 0)
            // or internal call failures would cause a revert; still acceptable to assert false
            // only when call succeeded; keep behavior observable via ok flag.
            assertTrue(false); // force fail if transfer reverted for admissible inputs
        }
    }
}

contract Recorder {
    uint256 public callCount;
    // must match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    // Declare exactly that function so ABI decoding occurs and we can record calls.
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        callCount += 1;
        return true;
    }
}
